example_item.example_item_data:
% Un enregistrement simule contamine, nettoye avec les valeurs par defaut.
recording = ecglab.simulate('Seconds', 30, 'Baseline', 0.5, ...
  'Mains', 0.1, 'MainsFrequency', 50, 'Seed', 1);
cleaned = ecglab.clean(recording);
cleaned.info.cleaning.mains

% La ligne de base par mediane a deux etages sur une derivation, sans secteur.
recording = ecglab.simulate('Seconds', 30, 'Baseline', 0.3, 'Seed', 2);
cleaned = ecglab.clean(recording, 'Baseline', 'median', 'Mains', false);
cleaned.info.cleaning.baselineRemoved
